// Cost Guard: keeps Claude Code spend visible and catches the two habits that
// cost the most: letting one session's context grow very large, and coming
// back to a big session after the prompt cache has expired.
//
// turn.complete: after each main-loop turn, read the session's cost and
// context from $.session.usage(), add the cost since the last reading to
// today's total in $.store, and toast when a context or budget threshold is
// crossed.
// prompt.submit: when the cache has expired (no turn for 5 minutes) and the
// context is big, hold the prompt once with an estimate of what resending it
// costs. Pressing Enter again sends it.
// session.start: register /cost-guard and keep the status line updated.

import type { EngineInterface, Register } from 'claude-code'

// Prompt cache entries expire after 5 minutes without use.
const CACHE_TTL_MS = 5 * 60 * 1000
const CONTEXT_STEP_TOKENS = 50_000
const DAY_KEYS_KEPT = 31

// List input price in USD per million tokens, matched on the model id.
// Writing to the cache costs 1.25x this; reading from it 0.1x or less.
const INPUT_PRICES: [RegExp, number][] = [
  [/fable|mythos/, 10],
  [/opus-5-5/, 4],
  [/opus/, 5],
  [/sonnet-5/, 2],
  [/sonnet/, 3],
  [/haiku/, 1],
]

type Reading = { tokens: number; costUsd: number | undefined; model: string }

let last: Reading = { tokens: 0, costUsd: undefined, model: '' }
let lastTurnAt = 0
let costSeen: number | undefined
let contextWarnedAt = 0
let sessionWarned = false
let dailyWarned = false
let heldAt = 0

export const register: Register = (on, options) => {
  const contextWarnTokens = Number(options.contextWarnTokens ?? 120_000)
  const coldGuardTokens = Number(options.coldGuardTokens ?? 60_000)
  const sessionBudgetUsd = Number(options.sessionBudgetUsd ?? 10)
  const dailyBudgetUsd = Number(options.dailyBudgetUsd ?? 25)

  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await $.command.register({
      name: 'cost-guard',
      description: 'Show session and daily spend, context size and cache state',
    })
    lastTurnAt = await $.clock.now()
    await takeReading($)
    costSeen = last.costUsd
    $.clock.every(15_000, () => void showStatus($))
    await showStatus($)

    return result
  })

  on('turn.complete', async ($, e, next) => {
    const result = await next(e)
    if (e.agentId !== undefined) {
      return result
    }
    lastTurnAt = await $.clock.now()
    heldAt = 0
    await takeReading($)
    const today = await addToToday($)

    if (last.tokens >= contextWarnTokens && last.tokens >= contextWarnedAt + CONTEXT_STEP_TOKENS) {
      contextWarnedAt = last.tokens
      $.ui.toast(
        `Context is ${short(last.tokens)} tokens. Every turn re-reads it: /clear when you switch tasks, /compact to keep going.`,
        { timeoutMs: 10_000 },
      )
    }
    if (!sessionWarned && (last.costUsd ?? 0) >= sessionBudgetUsd) {
      sessionWarned = true
      $.ui.toast(`This session has cost ${usd(last.costUsd ?? 0)}, past its ${usd(sessionBudgetUsd)} budget.`, {
        timeoutMs: 10_000,
      })
    }
    if (!dailyWarned && today >= dailyBudgetUsd) {
      dailyWarned = true
      $.ui.toast(`Today's spend is ${usd(today)}, past the ${usd(dailyBudgetUsd)} daily budget.`, {
        timeoutMs: 10_000,
      })
    }
    await showStatus($)

    return result
  })

  on('prompt.submit', async ($, e, next) => {
    const isTyped = e.origin.kind === 'composer' && e.turnId === undefined
    if (!isTyped || coldGuardTokens <= 0 || e.text.trimStart().startsWith('/')) {
      return next(e)
    }
    const now = await $.clock.now()
    const idleMs = now - lastTurnAt
    if (idleMs < CACHE_TTL_MS || last.tokens < coldGuardTokens || heldAt > lastTurnAt) {
      return next(e)
    }
    heldAt = now
    const rewrite = rewriteCost(last.tokens, last.model)
    // Put the prompt back so Enter sends it as typed.
    $.clock.after(50, () => void $.prompt.fill({ text: e.text }))

    return {
      drop:
        `Held once: the prompt cache expired ${minutes(idleMs)} ago, so this message re-writes ` +
        `${short(last.tokens)} tokens of context (~${usd(rewrite)}). Press Enter to send anyway, ` +
        `or /clear first if this is a new task.`,
    }
  })

  on('command.run', { command: 'cost-guard' }, async $ => {
    await takeReading($)
    const now = await $.clock.now()
    const days = await recentDays($, 7)
    const week = days.reduce((sum, day) => sum + day.usd, 0)
    const idleMs = now - lastTurnAt
    const cache =
      last.tokens === 0
        ? 'nothing cached yet'
        : idleMs < CACHE_TTL_MS
        ? `warm for ${minutes(CACHE_TTL_MS - idleMs)} more`
        : `expired ${minutes(idleMs)} ago: the next message re-writes ~${usd(rewriteCost(last.tokens, last.model))}`
    const lines = [
      `Session  ${last.costUsd === undefined ? 'n/a' : usd(last.costUsd)} (budget ${usd(sessionBudgetUsd)})`,
      `Today    ${usd(days[0]?.usd ?? 0)} (budget ${usd(dailyBudgetUsd)})`,
      `7 days   ${usd(week)}  ${days.map(day => `${day.date.slice(5)} ${usd(day.usd)}`).join(' · ')}`,
      `Context  ${short(last.tokens)} tokens on ${last.model || 'unknown model'}`,
      `Cache    ${cache}`,
      '',
      'Cheaper habits: /clear between tasks, /compact before a break, lower /effort for routine work,',
      'and /model to a Sonnet for everyday edits. Costs use list prices; a cloud provider may bill differently.',
    ]

    return { text: lines.join('\n') }
  })
}

async function takeReading($: EngineInterface) {
  try {
    const usage = await $.session.usage()
    last = {
      tokens: usage.context.tokens ?? 0,
      costUsd: usage.cost?.usd,
      model: await $.session.model(),
    }
  } catch {
    // Keep the last reading.
  }
}

// Adds the session's cost since the last reading to today's total; returns it.
async function addToToday($: EngineInterface) {
  const key = `day:${dateKey(await $.clock.now())}`
  const total = Number((await $.store.get(key)) ?? 0)
  if (last.costUsd === undefined) {
    return total
  }
  // /clear starts the session's cost over; count from the new figure.
  const delta = costSeen === undefined || last.costUsd < costSeen ? last.costUsd : last.costUsd - costSeen
  costSeen = last.costUsd
  if (delta <= 0) {
    return total
  }
  await $.store.set(key, total + delta)
  await pruneDays($)

  return total + delta
}

async function recentDays($: EngineInterface, count: number) {
  const now = await $.clock.now()
  const days: { date: string; usd: number }[] = []
  for (let i = 0; i < count; i++) {
    const date = dateKey(now - i * 86_400_000)
    days.push({ date, usd: Number((await $.store.get(`day:${date}`)) ?? 0) })
  }

  return days
}

async function pruneDays($: EngineInterface) {
  const keys = (await $.store.keys()).filter(key => key.startsWith('day:')).sort()
  for (const key of keys.slice(0, Math.max(0, keys.length - DAY_KEYS_KEPT))) {
    await $.store.delete(key)
  }
}

async function showStatus($: EngineInterface) {
  const idleMs = (await $.clock.now()) - lastTurnAt
  const today = Number((await $.store.get(`day:${dateKey(await $.clock.now())}`)) ?? 0)
  const parts = [
    last.costUsd === undefined ? undefined : `${usd(last.costUsd)} session`,
    `${usd(today)} today`,
    `ctx ${short(last.tokens)}`,
  ]
  if (last.tokens > 0) {
    parts.push(idleMs < CACHE_TTL_MS ? `cache ${minutes(CACHE_TTL_MS - idleMs)}` : 'cache cold')
  }
  $.ui.status(parts.filter(Boolean).join(' · '))
}

export function rewriteCost(tokens: number, model: string) {
  const price = INPUT_PRICES.find(([pattern]) => pattern.test(model))?.[1] ?? 5

  return (tokens / 1_000_000) * price * 1.25
}

function dateKey(ms: number) {
  const d = new Date(ms)
  const pad = (n: number) => String(n).padStart(2, '0')

  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`
}

function minutes(ms: number) {
  const total = Math.max(0, Math.round(ms / 1000))
  const m = Math.floor(total / 60)

  return m >= 60 ? `${Math.floor(m / 60)}h${String(m % 60).padStart(2, '0')}m` : `${m}:${String(total % 60).padStart(2, '0')}`
}

function short(n: number) {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${Math.round(n / 1_000)}k`

  return String(n)
}

function usd(n: number) {
  return `$${n.toFixed(2)}`
}

