{
  "name": "cost-guard",
  "version": "0.1.0",
  "description": "Watches session and daily spend, warns when the context grows large, and holds a prompt once when the prompt cache has expired on a big context.",
  "author": {
    "name": "Santiago Fernandez"
  },
  "userConfig": {
    "contextWarnTokens": {
      "type": "number",
      "title": "Context warning (tokens)",
      "description": "Toast when the context passes this size, and again every 50k above it.",
      "default": 120000
    },
    "coldGuardTokens": {
      "type": "number",
      "title": "Cold-cache guard (tokens)",
      "description": "Hold a prompt once when the cache has expired and the context is at least this big. 0 turns the guard off.",
      "default": 60000
    },
    "sessionBudgetUsd": {
      "type": "number",
      "title": "Session budget (USD)",
      "description": "Toast when this session's cost passes this amount.",
      "default": 10
    },
    "dailyBudgetUsd": {
      "type": "number",
      "title": "Daily budget (USD)",
      "description": "Toast when today's cost across sessions passes this amount.",
      "default": 25
    }
  }
}
